#[cfg(test)]
mod short_source_alias_memo_controls {
 use super::*;
 fn fixture()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){
  let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();
  for(id,x)in[(0,Expr::Sort(LevelId(0))),(1,Expr::Const{name:NameId(1),levels:vec![]}),(2,Expr::Pi{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Const{name:NameId(2),levels:vec![]}),(4,Expr::Const{name:NameId(3),levels:vec![]}),(5,Expr::BVar(0)),(6,Expr::Const{name:NameId(4),levels:vec![]}),(100,Expr::BVar(1)),(101,Expr::BVar(2))]{e.insert(ExprId(id),x).unwrap();}
  let mut body=ExprId(4);for id in 8..24{e.insert(ExprId(id),Expr::App{fun:ExprId(3),arg:body}).unwrap();body=ExprId(id);}
  let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![],ExprId(2))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![],ExprId(1))).unwrap().extend(NameId(4),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap();(e,l,env)
 }
 fn alias(c:&TypeChecker<'_>,index:u64,payload:ExprId)->Closure{let mut frame=EnvFrame::empty().extend(c.closure(payload,EnvFrame::empty()));for n in 0..index{frame=frame.extend_free(FreeId(90+n));}c.closure(match index{0=>ExprId(5),1=>ExprId(100),_=>ExprId(101)},frame)}
 #[test]fn alias_sort_reuse_requires_both_source_admission_and_complete_result_retention(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=alias(&c,0,ExprId(2));let first=c.infer_exact_closure_in_context(&t,&[],&mut 4096,0);assert!(matches!(first,Some(TypeValue::Sort(_))));let mut work=1;assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut work,0),first,"both alias admission and completed Sort retention are required");assert_eq!(work,0);}
 #[test]fn a_completed_short_alias_reuses_its_actual_derivation_with_one_paid_step(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);for index in[0,1]{let t=alias(&c,index,ExprId(23));let first=c.infer_exact_closure_in_context(&t,&[],&mut 4096,0);assert!(matches!(first,Some(TypeValue::Term(_))));let mut work=1;assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut work,0),first,"completed alias must reuse its own checked source derivation");assert_eq!(work,0);}}
 #[test]fn source_capture_universe_context_and_strictness_do_not_inherit_alias_typing(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let mut c=TypeChecker::new(&e,&l,&env);let t=alias(&c,0,ExprId(23));let g=vec![TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&g,&mut 4096,0);assert!(first.is_some());assert!(c.infer_exact_closure_in_context(&t,&g,&mut 0,0).is_none());assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,48).is_none());let wrong=alias(&c,0,ExprId(6));assert!(c.infer_exact_closure_in_context(&wrong,&g,&mut 1,0).is_none());assert_ne!(c.infer_exact_closure_in_context(&wrong,&g,&mut 4096,0),first);let changed=Closure::with_levels(t.expr,t.env.clone(),LevelSubstitution::new(vec![(NameId(99),LevelTerm::Zero)]));assert!(c.infer_exact_closure_in_context(&changed,&g,&mut 1,0).is_none());let h=vec![TypeValue::Term(c.closure(ExprId(6),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&h,&mut 1,0).is_none());c.strict_origin_probe=true;assert!(c.infer_exact_closure_in_context(&t,&g,&mut 1,0).is_none());}
 #[test]fn inherited_views_revocation_and_uncaptured_configuration_cannot_replay(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let mut c=TypeChecker::new(&e,&l,&env);let t=alias(&c,0,ExprId(23));assert!(c.infer_exact_closure_in_context(&t,&[],&mut 4096,0).is_some());c.inherited_binding_lineage=Some(InheritedBindings{ledger:c.checked_binding_lineage.clone(),epoch:c.binding_revocation_epoch.clone(),captured_epoch:c.binding_revocation_epoch.get()});assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());c.inherited_binding_lineage=None;c.binding_revocation_epoch.set(Some(1));assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());let other=TypeChecker::new(&e,&l,&env);assert!(other.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());drop(_scope);let uncaptured=TypeChecker::new(&e,&l,&env);assert!(uncaptured.infer_exact_closure_in_context(&t,&[],&mut 4096,0).is_some());assert!(uncaptured.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());}
 #[test]fn longer_aliases_still_require_the_original_derivation(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=alias(&c,2,ExprId(23));assert!(c.infer_exact_closure_in_context(&t,&[],&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());}
}
